add("gseb2024_30", ("(a) नेत्र की समंजन क्षमता की परिभाषा दीजिए।\n\n(b) पक्ष्माभी पेशी का कार्य लिखिए।", "(a) આંખની સમાવેશ-ક્ષમતાની વ્યાખ્યા આપો.\n\n(b) સિલિયરી સ્નાયુનું કાર્ય લખો."),
    {0: ("(a) पास और दूर की वस्तुएँ स्पष्ट देखने के लिए अभिनेत्र लेंस की अपनी फ़ोकस दूरी समायोजित करने की क्षमता।", "(a) નજીક અને દૂરની વસ્તુઓ સ્પષ્ટ જોવા નેત્રમણિની પોતાની કેન્દ્રલંબાઈ ગોઠવવાની ક્ષમતા."), 1: ("(b) पक्ष्माभी पेशियाँ अभिनेत्र लेंस की वक्रता, और इसलिए फ़ोकस दूरी, बदलती हैं।", "(b) સિલિયરી સ્નાયુઓ નેત્રમણિની વક્રતા, અને તેથી કેન્દ્રલંબાઈ, બદલે છે.")})
add("gseb2025_52", ("निकट-दृष्टि दोष और दीर्घ-दृष्टि दोष के बीच अंतर समझाइए।", "લઘુદૃષ્ટિ અને ગુરુદૃષ્ટિની ખામી વચ્ચેના તફાવત સમજાવો."),
    {0: ("निकट-दृष्टि: दूर की वस्तुएँ धुँधली; दूर बिंदु अनंत से पास। दीर्घ-दृष्टि: पास की वस्तुएँ धुँधली; निकट बिंदु 25 cm से दूर।", "લઘુદૃષ્ટિ: દૂરની વસ્તુઓ ઝાંખી; દૂરબિંદુ અનંત કરતાં નજીક. ગુરુદૃષ્ટિ: નજીકની વસ્તુઓ ઝાંખી; નજીકબિંદુ 25 cm કરતાં દૂર."),
     1: ("निकट-दृष्टि: प्रतिबिंब दृष्टिपटल के आगे बनता है (लेंस अधिक वक्रित या नेत्र गोलक लंबा)। दीर्घ-दृष्टि: प्रतिबिंब दृष्टिपटल के पीछे बनता है (फ़ोकस दूरी अधिक या नेत्र गोलक छोटा)।", "લઘુદૃષ્ટિ: પ્રતિબિંબ નેત્રપટલની આગળ બને છે (લેન્સ વધુ વક્ર કે ડોળો લાંબો). ગુરુદૃષ્ટિ: પ્રતિબિંબ નેત્રપટલની પાછળ બને છે (કેન્દ્રલંબાઈ વધુ કે ડોળો નાનો)."),
     2: ("निकट-दृष्टि अवतल लेंस से, दीर्घ-दृष्टि उत्तल लेंस से ठीक होती है।", "લઘુદૃષ્ટિ અંતર્ગોળ લેન્સથી, ગુરુદૃષ્ટિ બહિર્ગોળ લેન્સથી સુધરે છે.")})

